#include "graph_internal.hpp"
#include "hexlab/processors/format.hpp"
namespace hexlab::graph_detail {
namespace {
struct Writer {
    std::string text;std::stop_token stop;
    void add(std::string_view value){canceled(stop);if(value.size()>64*1024*1024-text.size())throw Failure{{ErrorCode::resource_limit,"Graph export exceeds 64 MiB"}};text+=value;}
    void quote(std::string_view raw){add("\"");auto value=safe_text(raw,262144);for(unsigned char c:value){switch(c){case '"':add("\\\"");break;case '\\':add("\\\\");break;case '\n':add("\\n");break;case '\r':add("\\r");break;case '\t':add("\\t");break;default:if(c<32){constexpr char digits[]="0123456789abcdef";char escape[]={'\\','u','0','0',digits[c>>4],digits[c&15]};add(std::string_view(escape,6));}else{char b=static_cast<char>(c);add(std::string_view(&b,1));}}}add("\"");}
    void number(uint64_t value){add(std::to_string(value));}
    void real(double value){require(std::isfinite(value),"Cannot export nonfinite graph geometry");std::array<char,64> buffer{};auto result=std::to_chars(buffer.data(),buffer.data()+buffer.size(),value,std::chars_format::general,17);require(result.ec==std::errc{},"Cannot encode graph coordinate");add(std::string_view(buffer.data(),result.ptr));}
    void id(uint64_t value){quote(hexadecimal(value));}
    void rect(GraphRect r){add("{\"x\":");real(r.x);add(",\"y\":");real(r.y);add(",\"width\":");real(r.width);add(",\"height\":");real(r.height);add("}");}
};
void check_model(const GraphModel& model,std::stop_token stop){validate_model(model,stop);require(model.key==Sha256Digest{} || model.key==fingerprint(model,stop),"Graph model fingerprint does not match contents");}
std::string json(const GraphModel& model,const GraphLayout* layout,std::stop_token stop){
    check_model(model,stop);if(layout){require(layout->model_key==fingerprint(model,stop),"Graph layout belongs to another model");require(layout->positions.size()==model.nodes.size() && layout->routes.size()==model.edges.size(),"Graph layout is incomplete");std::set<GraphNodeId> nodes;std::set<GraphEdgeId> edges;for(auto& n:model.nodes)nodes.insert(n.id);for(auto& e:model.edges)edges.insert(e.id);for(auto& p:layout->positions)require(nodes.erase(p.node)==1 && std::isfinite(p.bounds.x) && std::isfinite(p.bounds.y) && std::isfinite(p.bounds.width) && std::isfinite(p.bounds.height) && p.bounds.width>0 && p.bounds.height>0,"Invalid graph placement");for(auto& r:layout->routes)require(edges.erase(r.edge)==1 && r.points.size()>=2,"Invalid graph route");}
    Writer w{{},stop};w.add("{\"version\":1,\"kind\":");w.quote(model.kind==GraphKind::function_cfg?"function_cfg":model.kind==GraphKind::image_calls?"image_calls":"function_calls");w.add(",\"complete\":");w.add(model.complete?"true":"false");w.add(",\"omitted_nodes\":");w.number(model.omitted_nodes);w.add(",\"omitted_edges\":");w.number(model.omitted_edges);w.add(",\"nodes\":[");bool comma=false;
    for(auto& n:model.nodes){if(comma)w.add(",");comma=true;w.add("{\"id\":");w.id(n.id.value);w.add(",\"kind\":");w.number(static_cast<unsigned>(n.kind));w.add(",\"label\":");w.quote(n.label);w.add(",\"comment\":");w.quote(n.comment);w.add(",\"omitted_comment_bytes\":");w.number(n.omitted_comment_bytes);w.add(",\"selection\":");if(n.selection)w.quote(location_text(*n.selection));else w.add("null");w.add(",\"external\":");if(n.external){w.add("{\"library\":");w.quote(n.external->library);w.add(",\"name\":");if(n.external->name)w.quote(*n.external->name);else w.add("null");w.add(",\"ordinal\":");if(n.external->ordinal)w.number(*n.external->ordinal);else w.add("null");w.add("}");}else w.add("null");w.add(",\"body_preview\":[");size_t count=n.block?std::min(n.preview_lines,n.block->instructions.size()):0;for(size_t i=0;i<count;++i){if(i)w.add(",");w.quote(format_instruction(n.block->instructions[i]->instruction));}w.add("],\"instruction_count\":");w.number(n.block?n.block->instructions.size():0);w.add(",\"omitted_preview_lines\":");w.number(n.block?n.block->instructions.size()-count:0);w.add("}");}
    w.add("],\"edges\":[");comma=false;for(auto& e:model.edges){if(comma)w.add(",");comma=true;w.add("{\"id\":");w.id(e.id.value);w.add(",\"source\":");w.id(e.source.value);w.add(",\"target\":");w.id(e.target.value);w.add(",\"kind\":");w.number(static_cast<unsigned>(e.kind));w.add(",\"boundary\":");w.add(e.boundary?"true":"false");w.add(",\"reference\":");if(e.reference)w.id(e.reference->value);else w.add("null");w.add(",\"selection\":");if(e.selection)w.quote(location_text(*e.selection));else w.add("null");w.add(",\"target_location\":");if(e.target_location)w.quote(location_text(*e.target_location));else w.add("null");w.add("}");}w.add("]");
    if(layout){w.add(",\"layout\":{\"bounds\":");w.rect(layout->bounds);w.add(",\"positions\":[");comma=false;for(auto& p:layout->positions){if(comma)w.add(",");comma=true;w.add("{\"node\":");w.id(p.node.value);w.add(",\"x\":");w.real(p.bounds.x);w.add(",\"y\":");w.real(p.bounds.y);w.add(",\"width\":");w.real(p.bounds.width);w.add(",\"height\":");w.real(p.bounds.height);w.add("}");}w.add("],\"routes\":[");comma=false;for(auto& r:layout->routes){if(comma)w.add(",");comma=true;w.add("{\"edge\":");w.id(r.edge.value);w.add(",\"points\":[");bool point_comma=false;for(auto p:r.points){if(point_comma)w.add(",");point_comma=true;w.add("{\"x\":");w.real(p.x);w.add(",\"y\":");w.real(p.y);w.add("}");}w.add("]}");}w.add("]}");}w.add("}");return std::move(w.text);
}
}
}
namespace hexlab {
Result<std::string> export_graph_json(const GraphModel& model,std::stop_token stop){return graph_detail::guarded([&]()->Result<std::string>{return graph_detail::json(model,nullptr,stop);});}
Result<std::string> export_graph_json(const GraphModel& model,const GraphLayout& layout,std::stop_token stop){return graph_detail::guarded([&]()->Result<std::string>{return graph_detail::json(model,&layout,stop);});}
Result<std::string> export_graph_dot(const GraphModel& model,std::stop_token stop){return graph_detail::guarded([&]()->Result<std::string>{using namespace graph_detail;check_model(model,stop);Writer w{{},stop};w.add("digraph HexLab {\n  graph [charset=\"UTF-8\"];\n");for(auto& n:model.nodes){w.add("  n");w.add(hexadecimal(n.id.value));w.add(" [label=");w.quote(n.label);w.add("];\n");}for(auto& e:model.edges){w.add("  n");w.add(hexadecimal(e.source.value));w.add(" -> n");w.add(hexadecimal(e.target.value));w.add(" [id=");w.quote(hexadecimal(e.id.value));w.add(", label=");w.quote(std::to_string(static_cast<unsigned>(e.kind)));w.add("];\n");}w.add("}\n");return std::move(w.text);});}
}
